import fs from 'node:fs';
import {practicalCopy} from './practical-content.mjs';
const review={};
const put=(id,de,es,it,fr,zh)=>{if(!practicalCopy[id])throw Error('Unknown practical copy '+id);review[practicalCopy[id]]={de,es,it,fr,zh};};
put('diagramNote','Schnittstellenskizze, nicht maßstäblich. Maße und Abnahme richten sich nach der freigegebenen Baugruppenzeichnung.','Esquema de interfaces, no a escala. Las cotas y la aceptación se definen en el plano aprobado del conjunto.','Schema delle interfacce, non in scala. Quote e accettazione seguono il disegno approvato dell’assieme.','Schéma des interfaces, sans échelle. Les cotes et la réception suivent le plan d’ensemble approuvé.','接口结构示意，不按比例绘制。尺寸与验收要求以批准的装配图为准。');
put('homeLink','Unternehmen und Musterplanung','Empresa y planificación de muestras','Azienda e pianificazione dei campioni','Entreprise et préparation des échantillons','了解企业与打样安排');
put('companyTitle','Meilensteine vor dem Werkzeugbau vereinbaren','Acordar los hitos antes de fabricar el utillaje','Concordare le fasi prima di avviare gli stampi','Définir les étapes avant de lancer l’outillage','开模前，先把各阶段的确认事项说清楚');
put('companyIntro','Trennen Sie Angebot, Musterfreigabe und Serienauftrag. So bleibt klar, was kalkuliert wird, was das Muster nachweisen soll und welche Punkte für den Auftrag noch abzustimmen sind.','Separe la oferta, la aprobación de muestras y la producción repetitiva. Así queda claro qué se está cotizando, qué debe demostrar la muestra y qué falta acordar para el pedido.','Distinguere preventivo, approvazione dei campioni e produzione ripetitiva: chiarire cosa viene quotato, cosa deve dimostrare il campione e quali aspetti dell’ordine restano da concordare.','Distinguez devis, approbation des échantillons et production récurrente : précisez ce qui est chiffré, ce que l’échantillon doit démontrer et les points restant à convenir pour la commande.','报价、样品批准和后续量产是不同的确认环节。先明确报价包含什么、样品要验证什么，以及订单还有哪些待定事项，后续沟通才有共同依据。');
put('companyReviewTitle','Zeichnung und Angebot','Plano y oferta','Disegno e preventivo','Plan et devis','图纸评审与报价');
put('companyReview','Benennen Sie aktuelle Zeichnung, Gegenstücke, Werkstoff, Oberfläche und kritische Merkmale. Halten Sie offene Punkte und Angebotsannahmen fest, einschließlich Fertigungsroute und extern vorgesehener Bearbeitung oder Prüfung.','Identifique el plano vigente, las piezas acopladas, el material, el acabado y las características críticas. Registre las dudas y los supuestos de la oferta, incluida la ruta propuesta y los procesos o ensayos previstos con terceros.','Identificare disegno aggiornato, componenti accoppiati, materiale, finitura e caratteristiche critiche. Registrare punti aperti e ipotesi di preventivo, compresi ciclo proposto e lavorazioni o prove affidate all’esterno.','Identifiez le plan en vigueur, les pièces en regard, le matériau, la finition et les caractéristiques critiques. Consignez les points ouverts et hypothèses du devis, y compris la gamme proposée et les opérations ou essais prévus en externe.','明确现行图纸、配合件、材料、表面处理和关键特征。把尚未解决的问题、报价采用的假设、拟定工艺路线，以及拟安排的外部加工或检测一并记录下来。');
put('companySampleTitle','Werkzeuge und Muster','Utillaje y muestras','Stampi e campioni','Outillage et échantillons','模具与打样');
put('companySample','Für Werkzeugbau und Bemusterung sind etwa 10–15 Tage einzuplanen, vorbehaltlich technischer Prüfung und Angebotsbestätigung. Vereinbaren Sie vor Beginn Startpunkt, Musterzahl und Prüfungen; die Musterfreigabe bleibt ein eigener Schritt.','Prevea aproximadamente 10–15 días para utillaje y muestras, sujetos a revisión técnica y confirmación de la oferta. Antes de empezar, acuerde el hito de inicio, la cantidad y las comprobaciones; la aprobación de la muestra es una decisión aparte.','Prevedere circa 10–15 giorni per stampi e campioni, previa valutazione tecnica e conferma del preventivo. Concordare prima dell’avvio il momento iniziale, la quantità e i controlli; l’approvazione del campione è una fase distinta.','Prévoyez environ 10–15 jours pour l’outillage et les échantillons, sous réserve de revue technique et de confirmation du devis. Convenez au préalable du point de départ, de la quantité et des contrôles ; l’approbation des échantillons est une étape distincte.','含模具打样通常约需 10–15 天，具体经技术评审和报价确认。开始前约定周期起算节点、样品数量与检查项目；样品完成后，还需单独确认是否批准。');
put('companyRepeatTitle','Wiederholaufträge','Producción repetitiva','Produzione ripetitiva','Production récurrente','后续量产');
put('companyRepeat','Vereinbaren Sie anhand von freigegebenem Muster und Zeichnungsstand Menge, Loskennzeichnung, Unterlagen und Lieferung. Die monatliche Kapazität liegt über den Produktmix hinweg bei mehreren Millionen Teilen; Einplanung und Termine hängen von Route und Auftrag ab.','Con la muestra y la revisión del plano aprobadas, acuerde cantidad, identificación de lote, documentos y entrega. La capacidad mensual es de varios millones de piezas entre distintos productos; la asignación y los plazos dependen de la ruta y del pedido.','Con campione e revisione del disegno approvati, concordare quantità, identificazione del lotto, documenti e consegna. La capacità mensile è di alcuni milioni di pezzi nell’insieme dei prodotti; pianificazione e tempi dipendono dal ciclo e dall’ordine.','À partir de l’échantillon et de l’indice du plan approuvés, convenez de la quantité, de l’identification du lot, des documents et de la livraison. La capacité mensuelle est de plusieurs millions de pièces, tous produits confondus ; l’allocation et les délais dépendent de la gamme et de la commande.','以批准的样品和图纸版本为依据，约定订单数量、批次标识、所需文件与交付安排。不同产品合计月产能约数百万件，具体排产和交期取决于实际工艺与订单条件。');
put('companyNext','Anforderungen an die Musterfreigabe vorbereiten','Preparar los requisitos de aprobación de muestras','Preparare i requisiti di approvazione dei campioni','Préparer les exigences d’approbation des échantillons','准备样品批准要求');
put('companyPhoto','Vom Unternehmen bereitgestelltes Foto von Gewindeteilen und Schulterformen','Fotografía aportada por la empresa de componentes roscados y piezas con hombro','Fotografia fornita dall’azienda di componenti filettati e forme a spallamento','Photographie fournie par l’entreprise de pièces filetées et de formes à épaulement','企业提供的螺纹件与台阶类样件实拍');
put('companyCaption','Produktformen aus den vom Unternehmen bereitgestellten Musterfotos.','Formas de producto en las fotografías de muestras aportadas por la empresa.','Forme dei prodotti nelle fotografie dei campioni fornite dall’azienda.','Formes de pièces visibles sur les photographies d’échantillons fournies par l’entreprise.','企业提供的样件实拍，展示可见的产品结构。');
put('shoulderTitle','Bohrungspassung und Axialspiel getrennt prüfen','Comprobar por separado el ajuste del hombro y la holgura axial','Verificare separatamente accoppiamento del gambo e gioco assiale','Vérifier séparément l’ajustement dans l’alésage et le jeu axial','孔轴配合与轴向间隙，要分别确认');
put('shoulderIntro','Die Paarung aus Schulter und Bohrung führt die Bewegung; der Abstand zwischen den Anlageflächen bestimmt die axiale Maßkette. Legen Sie beides im Lieferzustand fest, statt die Gewindepassung als Zentrierpassung zu behandeln.','El hombro y el taladro guían el movimiento; la distancia entre las caras de apoyo determina la cadena axial. Defina ambas interfaces en el estado final de suministro, sin tratar el ajuste de rosca como ajuste de guiado.','L’accoppiamento tra gambo calibrato e foro guida il movimento; la distanza tra le facce d’appoggio determina la catena assiale. Definire entrambi nello stato finale di fornitura, senza confondere l’accoppiamento filettato con quello di guida.','L’épaulement et l’alésage guident le mouvement ; la distance entre les faces d’appui définit la chaîne axiale. Précisez les deux dans l’état final de livraison, sans assimiler l’ajustement du filetage à celui du guidage.','肩轴与配合孔负责导向，两处支承端面之间的距离决定轴向尺寸链。两类要求都应按最终交付状态定义，不能把螺纹配合等级当作定位轴段的配合要求。');
put('shoulderOne','Schulter und Gegenbohrung: beide Maßgrenzen, Bezugsachse und funktionale Oberflächenanforderungen angeben.','Hombro y taladro: indique los límites de ambas cotas, el eje de referencia y los requisitos funcionales de superficie.','Gambo e foro: indicare i limiti delle due quote, l’asse di riferimento e gli eventuali requisiti funzionali della superficie.','Épaulement et alésage : indiquez les limites des deux cotes, l’axe de référence et les exigences fonctionnelles de surface.','肩轴与配合孔：分别注明尺寸上下限、参考轴线，以及影响功能的表面要求。');
put('shoulderTwo','Anlage und Übergang: Fase oder Senkung des Gegenstücks zeigen, damit unvollständiges Gewinde oder Freistich die Anlage nicht verhindern.','Apoyo y transición: muestre el chaflán o alojamiento de la pieza acoplada para que el filete incompleto o la garganta no impidan el asiento.','Appoggio e transizione: mostrare smusso o lamatura del componente accoppiato, evitando interferenze del filetto incompleto o dello scarico.','Appui et transition : représentez le chanfrein ou le lamage de la pièce en regard pour éviter toute interférence du filet incomplet ou du dégagement.','端面与过渡段：画出配合件的倒角或沉孔，核对不完整牙、退刀槽及其相邻结构是否妨碍贴合。');
put('shoulderThree','Nach der Oberflächenbearbeitung: betroffene Flächen und den Prüfzeitpunkt der endgültigen Passung festlegen.','Tras el acabado: identifique las superficies afectadas por el tratamiento o recubrimiento y cuándo se comprobará el ajuste final.','Dopo la finitura: identificare le superfici interessate dal trattamento o rivestimento e la fase di controllo dell’accoppiamento finale.','Après finition : identifiez les surfaces affectées par le traitement ou le revêtement et l’étape de contrôle de l’ajustement final.','处理后的状态：标明热处理或涂层会影响哪些表面，并约定最终配合尺寸在哪道工序后验收。');
put('shoulderOutcome','Lesen Sie die folgende Spielberechnung zusammen mit diesen Schnittstellen. Ein ausreichendes Axialspiel belegt allein weder die Bohrungspassung noch die geforderte geometrische Beziehung.','Revise el cálculo de holgura de abajo junto con estas interfaces. Una holgura axial correcta no confirma por sí sola el ajuste del taladro ni la relación geométrica exigida.','Leggere il calcolo del gioco riportato sotto insieme a queste interfacce. Un gioco assiale corretto non verifica da solo l’accoppiamento nel foro o la relazione geometrica richiesta.','Lisez le calcul du jeu ci-dessous avec ces interfaces. Un jeu axial satisfaisant ne valide à lui seul ni l’ajustement dans l’alésage ni la relation géométrique requise.','下方的间隙算例应结合这些接口一起看。轴向间隙合适，并不代表孔轴配合及几何关系也已经满足要求。');
put('captiveTitle','Unverlierbare Schrauben in beiden Wartungsstellungen prüfen','Revisar el tornillo imperdible en las dos posiciones de servicio','Verificare la vite imperdibile nelle due posizioni di servizio','Examiner la vis imperdable dans ses deux positions de service','防脱螺丝，打开和锁紧两种状态都要看');
put('captiveIntro','Eine unverlierbare Schraube gehört zu einer Baugruppe aus Platte und Halteelement. Prüfen Sie die gelöste Stellung ebenso sorgfältig wie die angezogene: nutzbarer Gewindeeingriff und gehaltener Hub sind unterschiedliche Anforderungen.','El tornillo imperdible forma parte del panel y su retenedor. Revise la posición liberada igual que la apretada: el acoplamiento útil de rosca y el recorrido retenido son requisitos distintos.','La vite imperdibile fa parte di un sistema con pannello ed elemento di ritegno. Verificare la posizione svitata quanto quella serrata: l’impegno utile del filetto e la corsa trattenuta sono requisiti diversi.','La vis imperdable fait partie d’un ensemble comprenant panneau et dispositif de retenue. Vérifiez autant la position desserrée que serrée : longueur utile d’engagement et course retenue répondent à des exigences distinctes.','防脱螺丝要与面板、保持件一起评审。打开后的状态与锁紧状态同样重要：有效旋合长度是否足够、松开后能移动多远，是两个不同的问题。');
put('captiveOne','Gelöst: Die Schraube ist vom Gegengewinde frei, bleibt aber durch das gewählte Halteelement an der Platte.','Liberado: el tornillo sale de la rosca receptora, pero el retenedor elegido lo mantiene unido al panel.','Svitata: la vite si disimpegna dalla filettatura accoppiata, ma il ritegno scelto la mantiene nel pannello.','Desserrée : la vis se dégage du taraudage tout en restant solidaire du panneau grâce au dispositif de retenue choisi.','打开时：螺纹已退出配合件，选定的保持结构仍能把螺丝留在面板上。');
put('captiveTwo','Angezogen: Der Kopf liegt richtig an, das Halteelement hat Bewegungsraum und der erforderliche Gewindeeingriff bleibt verfügbar.','Apretado: la cabeza apoya correctamente, el retenedor dispone de espacio y se mantiene el acoplamiento de rosca requerido.','Serrata: la testa appoggia correttamente, il ritegno ha spazio e rimane disponibile l’impegno di filetto richiesto.','Serrée : la tête porte correctement, le dispositif de retenue dispose de son espace et l’engagement requis reste disponible.','锁紧时：头部按设计贴合，保持件有足够活动空间，螺纹仍能达到要求的旋合长度。');
put('captiveThree','Baugruppenprüfung: Plattendicke, Haltebohrung, Geometrie des Halteelements und Montagereihenfolge angeben.','Revisión del conjunto: aporte espesor del panel, detalles del orificio de retención, geometría del retenedor y secuencia de montaje.','Revisione dell’assieme: fornire spessore del pannello, foro di ritegno, geometria del fermo e sequenza di montaggio.','Revue de l’ensemble : fournissez l’épaisseur du panneau, le trou de retenue, la géométrie du dispositif et la séquence de montage.','装配评审时：同时提供板厚、保持孔结构、保持件几何和安装顺序。');
put('captiveOutcome','Vereinbaren Sie Halteprüfung und Demontage-/Montageversuch getrennt von der Gewindeprüfung. Die Skizze zeigt beispielhaft ein separates Halteelement; die tatsächliche Lösung muss zur Baugruppe passen.','Acuerde por separado la prueba de retención, el ensayo de desmontaje y montaje, y el control de rosca. El esquema ilustra un retenedor independiente; la solución real debe corresponder al conjunto.','Concordare controllo del ritegno e prova di smontaggio/rimontaggio separatamente dalla verifica del filetto. Lo schema mostra un fermo separato a titolo d’esempio; la soluzione reale deve corrispondere all’assieme.','Convenez du contrôle de retenue et de l’essai de démontage/remontage séparément du contrôle du filetage. Le schéma illustre un dispositif séparé ; la solution réelle doit correspondre à l’ensemble.','保持性能、拆装操作与螺纹通止规检查应分别约定。图中以独立保持件举例，实际保持方式仍需与完整装配结构匹配。');
put('securityTitle','Antrieb und Werkzeugzugang im Einbauzustand abstimmen','Comprobar el acceso de la herramienta a la huella instalada','Coordinare impronta e accesso dell’utensile nel montaggio','Adapter l’empreinte à l’accès de l’outil une fois la vis montée','槽型选好，还要确认装机后工具进得去');
put('securityIntro','Wählen Sie das Antriebsprofil gemeinsam mit Wartungswerkzeug und Gehäuse. Ein passender Bit hilft nur, wenn er die eingebaute Schraube erreichen, vollständig greifen und drehen kann.','Seleccione la huella junto con la herramienta de mantenimiento y la carcasa. La punta correcta solo sirve si puede alcanzar, acoplar y girar el tornillo instalado.','Scegliere l’impronta insieme all’utensile di manutenzione e all’involucro. Un inserto compatibile serve solo se può raggiungere, impegnare e ruotare la vite montata.','Choisissez l’empreinte avec l’outil de maintenance et le boîtier. Un embout compatible n’est utile que s’il peut atteindre, engager et tourner la vis montée.','防拆槽型要结合维修工具和外壳一起选。批头即使匹配，也得能接近已安装的螺丝、充分啮合并顺利转动。');
put('securityOne','Antrieb und Bit: Profil und Eingriffstiefe festlegen; bei Antrieb mit Stift auch Stift und Freiraum des passenden Bits.','Huella y punta: defina el perfil y la profundidad de acoplamiento; en una huella con tetón, incluya el tetón y la holgura de la punta correspondiente.','Impronta e inserto: definire profilo e profondità d’impegno; per l’impronta con perno, anche perno e spazio nell’inserto corrispondente.','Empreinte et embout : précisez le profil et la profondeur d’engagement ; pour une empreinte avec téton, ajoutez le téton et le dégagement de l’embout adapté.','槽型与批头：明确实际轮廓和啮合深度；带柱槽型还要核对中柱与配套批头的避让空间。');
put('securityTwo','Zugangsraum: Werkzeugansatz, benachbarte Wände sowie Einsteck- und Ausziehraum darstellen.','Envolvente de acceso: muestre la aproximación de la herramienta, las paredes próximas y el espacio para introducirla y retirarla.','Ingombro d’accesso: mostrare avvicinamento dell’utensile, pareti vicine e spazio d’inserimento ed estrazione.','Enveloppe d’accès : représentez l’approche de l’outil, les parois voisines et l’espace nécessaire à son insertion et à son retrait.','工具空间：画出工具进入方向、邻近壁面，以及插入和退出所需的空间。');
put('securityThree','Wartungsversuch: Montage und autorisierte Demontage mit repräsentativem Gehäuse und passendem Werkzeug prüfen.','Prueba de servicio: compruebe el montaje y la retirada autorizada con la carcasa representativa y la herramienta correspondiente.','Prova di servizio: verificare installazione e rimozione autorizzata con involucro rappresentativo e utensile corretto.','Essai de maintenance : vérifiez la pose et la dépose autorisée avec un boîtier représentatif et l’outil adapté.','维护验证：使用有代表性的外壳和配套工具，确认安装及授权拆卸都能完成。');
put('securityOutcome','Antriebsabnahme und Zugangsprüfung getrennt behandeln. Ein Profil mit Stift kann unbefugtes Lösen erschweren, begründet allein aber keine Sicherheitsklasse.','Separe la aceptación de la huella y la del acceso. Un perfil con tetón puede dificultar la manipulación casual, pero por sí solo no establece una clasificación de seguridad.','Separare accettazione dell’impronta e verifica dell’accesso. Un profilo con perno può limitare lo smontaggio occasionale, ma non determina da solo una classe di sicurezza.','Distinguez réception de l’empreinte et vérification de l’accès. Un profil avec téton peut limiter les démontages non autorisés courants, sans établir à lui seul un niveau de sécurité.','槽型合格与工具可达应分别确认。带柱结构可以限制随意拆卸，但仅凭槽型不能认定整机具有某种安全等级。');
put('hollowTitle','Kleinsten Restquerschnitt und verdeckte Bohrungskante verfolgen','Revisar la pared mínima y la arista interior oculta','Verificare la parete minima e lo spigolo interno nascosto','Examiner la paroi minimale et l’arête intérieure masquée','最薄的剩余壁厚、藏在孔内的毛刺，都要看得到');
put('hollowIntro','Verbinden Sie Durchgang und Außenmerkmale in einer Schnittansicht. Der kleinste Restquerschnitt kann am Gewindegrund oder an einer Querbohrung liegen, nicht am größten Außendurchmesser.','Relacione el conducto con los detalles exteriores mediante una sección. La pared mínima puede estar junto a la raíz de rosca o a una intersección, no en el diámetro exterior mayor.','Collegare il passaggio alle forme esterne con una sezione. La parete residua critica può trovarsi al fondo del filetto o all’incrocio di un foro, non al diametro esterno maggiore.','Reliez le passage aux formes extérieures par une vue en coupe. La paroi résiduelle critique peut se situer au fond du filet ou à une intersection, plutôt qu’au plus grand diamètre extérieur.','用剖视图把孔道与外部结构联系起来。最薄截面可能出现在螺纹牙底或交叉孔附近，不能只看最大外径处的壁厚。');
put('hollowOne','Gewindegrund zur Bohrung: Restquerschnitt anhand der geltenden Gewindegeometrie und der Bohrungslage festlegen.','Raíz de rosca y taladro: defina la sección restante con la geometría de rosca aplicable y la posición del taladro.','Fondo del filetto e foro: definire la sezione residua in base alla geometria del filetto applicabile e alla posizione del foro.','Fond du filet et alésage : définissez la section restante à partir de la géométrie du filetage et de la position de l’alésage.','螺纹牙底到内孔：结合实际牙型和孔的位置，明确需要保留的截面。');
put('hollowTwo','Bohrungskreuzung: Innenkante, Gratanforderung sowie einen ausführbaren Entgrat- und Prüfweg benennen.','Intersección de taladros: identifique la arista interna, el requisito de rebaba y un procedimiento viable de desbarbado e inspección.','Incrocio dei fori: identificare spigolo interno, requisito sulle bave e un percorso praticabile di sbavatura e controllo.','Intersection des perçages : identifiez l’arête intérieure, l’exigence d’ébavurage et une méthode réalisable de traitement et de contrôle.','孔道交汇处：明确内部边缘、毛刺要求，以及可实际执行的去毛刺和复检方式。');
put('hollowThree','Fertiger Durchgang: lichte Bohrung, Ein-/Auslaufkanten und Reinigung vereinbaren, bevor die Montage den Zugang verhindert.','Conducto terminado: acuerde paso libre, aristas de entrada y salida y limpieza antes de que el montaje impida acceder al interior.','Passaggio finito: concordare luce del foro, condizioni d’ingresso e uscita e pulizia prima che il montaggio impedisca l’accesso.','Passage fini : convenez de la section libre, de l’état des entrées et sorties et du nettoyage avant que le montage ne rende l’intérieur inaccessible.','最终孔道：在装配后难以进入内部之前，确认通孔净空、入口出口边缘状态和清洗要求。');
put('hollowOutcome','CCD-Screening der Außenkontur kann sichtbare Merkmale prüfen. Verdeckte Bohrungsmerkmale benötigen ein geeignetes separates Verfahren. Die folgende Anwendungsmatrix unterscheidet Kabeldurchführung, Strömung und Abdichtung.','El cribado CCD exterior puede comprobar el perfil visible. Verifique las características interiores inaccesibles con otro método adecuado y use la matriz siguiente para distinguir paso de cables, caudal y sellado.','Il controllo CCD esterno può verificare il profilo visibile. Per le parti interne non accessibili usare un metodo separato adeguato; la matrice seguente distingue passaggio cavi, flusso e tenuta.','Le contrôle CCD extérieur peut vérifier le profil visible. Contrôlez les caractéristiques internes inaccessibles par une méthode complémentaire adaptée ; la matrice ci-dessous distingue passage de câbles, écoulement et étanchéité.','外部 CCD 筛选可用于可见轮廓，无法进入或成像的内部特征应另选合适方法。再结合下方用途矩阵，分别确认走线、流通和密封的要求。');
put('flangeTitle','Auflagefläche vergleichen, bevor der Flansch vergrößert wird','Comparar el apoyo antes de aumentar la brida','Confrontare l’appoggio prima di ingrandire la flangia','Comparer l’appui avant d’agrandir l’embase','先看承压面的接触方式，再决定法兰做多大');
put('flangeIntro','Ein größerer Flansch verändert die Kontaktfläche; ob dieser Kontakt sinnvoll ist, bestimmt weiterhin das geklemmte Bauteil. Prüfen Sie Stirnfläche, Beschichtung und verfügbaren Sitz gemeinsam.','Una brida mayor cambia la zona de contacto, pero la pieza sujetada sigue determinando si ese contacto resulta útil. Compare la cara de apoyo, el recubrimiento y el asiento disponible.','Una flangia più grande cambia l’area di contatto, ma è il componente serrato a determinare se tale contatto è utile. Valutare insieme faccia, rivestimento e superficie d’appoggio disponibile.','Une embase plus grande modifie la zone de contact, mais c’est la pièce serrée qui détermine l’utilité de cet appui. Comparez face, revêtement et surface d’appui disponible.','法兰加大改变的是接触范围，是否适合仍要看被夹紧零件。应把承压面、配合件涂层和实际可用的贴合区域放在一起评估。');
put('flangeOne','Glatter integrierter Flansch: nutzbare Auflagefläche, angrenzende Radien und Freiraum zur Gegensenkung festlegen.','Brida integral lisa: defina la cara útil de apoyo, los radios próximos y la holgura con el alojamiento acoplado.','Flangia integrata liscia: definire faccia utile d’appoggio, raggi adiacenti e spazio rispetto alla sede accoppiata.','Embase lisse intégrée : définissez la face utile d’appui, les rayons voisins et le dégagement dans le logement en regard.','光面一体法兰：明确有效承压面、相邻圆角，以及与配合件沉台的避让。');
put('flangeTwo','Verzahnter integrierter Flansch: vorgesehenen Zahnkontakt, zulässige Abdrücke und Auswirkungen auf die Beschichtung prüfen.','Brida integral dentada: revise el contacto previsto de los dientes, las marcas permitidas y el efecto sobre el recubrimiento.','Flangia integrata dentellata: verificare contatto dei denti, impronte ammesse ed effetto sul rivestimento del componente accoppiato.','Embase crantée intégrée : examinez le contact des dents, les marques admissibles et l’effet sur le revêtement en regard.','齿面一体法兰：评估齿部接触位置、允许压痕，以及对配合件涂层的影响。');
put('flangeThree','Separate Scheibe: Maße, Härte oder sonstigen geforderten Zustand sowie den Beitrag zur axialen Maßkette berücksichtigen.','Arandela independiente: incluya dimensiones, dureza u otra condición exigida y su contribución a la cadena axial.','Rondella separata: includere dimensioni, durezza o altra condizione richiesta e contributo alla catena assiale.','Rondelle séparée : précisez dimensions, dureté ou autre état requis, ainsi que sa contribution à la chaîne axiale.','独立垫片：计入垫片尺寸、硬度或其他规定状态，以及它对轴向尺寸链的影响。');
put('flangeOutcome','Halten Sie fest, welche Flächen anliegen dürfen und welche frei bleiben müssen. Bei Abdrücken, Vorspannung oder wiederholter Wartung ist ein Versuch mit dem tatsächlichen Oberflächensystem zu vereinbaren, statt die Wirkung allein aus dem Flanschdurchmesser abzuleiten.','Registre qué caras deben contactar y cuáles deben quedar libres. Si importan las marcas, la precarga o el mantenimiento repetido, acuerde una prueba del sistema superficial real en lugar de deducir el rendimiento del diámetro de brida.','Registrare quali facce devono toccare e quali devono restare libere. Se contano impronte, precarico o manutenzione ripetuta, concordare una prova sul sistema superficiale reale senza dedurre le prestazioni dal diametro della flangia.','Consignez les faces autorisées au contact et celles devant rester dégagées. Si les marques, la précharge ou la maintenance répétée sont importantes, convenez d’un essai avec le système de surface réel plutôt que de déduire les performances du diamètre d’embase.','注明哪些面可以接触、哪些位置必须留空。若关注压痕、预紧或反复拆装，应针对实际表面体系约定装配验证，不能从法兰直径直接推断性能。');
put('setTitle','Spitzenform nach dem Kontakt zum Gegenstück wählen','Elegir la punta según el contacto con la pieza acoplada','Scegliere la punta in base al contatto con il componente accoppiato','Choisir l’extrémité selon son contact avec la pièce en regard','先看顶端怎样接触配合件，再选机米端型');
put('setIntro','Die Spitzenform bestimmt den Kontaktmechanismus. Wählen Sie sie anhand von Gegenfläche, Verstellhäufigkeit und zulässigen Abdrücken; legen Sie anschließend nutzbares Gewinde und Werkzeugzugang fest.','La forma de la punta determina el contacto. Elíjala según la superficie acoplada, la frecuencia de ajuste y las marcas admisibles; después defina rosca útil y acceso de la herramienta.','La forma della punta determina il contatto. Sceglierla con superficie accoppiata, frequenza di regolazione e impronte ammesse, quindi definire filetto utile e accesso dell’utensile.','La forme de l’extrémité détermine le contact. Choisissez-la selon la surface en regard, la fréquence de réglage et les marques admissibles, puis précisez filetage utile et accès de l’outil.','端型决定接触方式。结合配合面、调整频率和允许压痕选定结构，再明确有效螺纹及工具操作空间。');
put('setOne','Flachspitze: Gegenfläche festlegen und zulässige Kontaktabdrücke vereinbaren.','Punta plana: defina la superficie acoplada y las marcas de contacto admisibles.','Punta piana: definire la faccia accoppiata e le impronte di contatto ammesse.','Bout plat : définissez la face en regard et les marques de contact admissibles.','平端：明确配合端面，并约定允许留下的接触痕迹。');
put('setTwo','Kegelspitze: vorgesehene Vertiefung oder zulässige Eindrückung und deren Position darstellen.','Punta cónica: muestre el rebaje previsto o la indentación permitida y la posición donde debe actuar.','Punta conica: mostrare incavo previsto o impronta consentita e posizione d’impegno.','Bout conique : représentez le logement prévu ou l’indentation autorisée et sa position.','尖端：画出预设凹位或允许形成的压痕，以及应接触的位置。');
put('setThree','Zapfen: Überstand und Gegenbohrung oder Nut festlegen; Spiel und verfügbare Tiefe prüfen.','Punta cilíndrica: defina la proyección y el agujero o ranura acoplados; compruebe holgura y profundidad disponible.','Punta cilindrica: definire sporgenza e foro o cava accoppiati; verificare gioco e profondità disponibile.','Téton : définissez la saillie et le trou ou la rainure en regard ; vérifiez jeu et profondeur disponible.','圆柱端：明确伸出长度及配合孔或槽，同时检查间隙与可用深度。');
put('setFour','Ringschneide: Randkontakt und Eindrückung mit der zulässigen Beschädigung der Gegenfläche abgleichen.','Punta de copa: revise el contacto del borde y la indentación frente al daño permitido en la superficie acoplada.','Punta a coppa: verificare contatto del bordo e impronta rispetto al danneggiamento ammesso della superficie accoppiata.','Bout cuvette : comparez le contact du bord et l’indentation à l’endommagement admissible de la surface en regard.','凹端：结合边缘接触和压入情况，核对配合面允许的损伤程度。');
put('setOutcome','Prüfen Sie wiederholtes Verstellen und Haltewirkung an der tatsächlichen Verbindung. Spitzenform und Schraubendurchmesser allein liefern keinen allgemeingültigen Wert für Haltekraft oder Anziehdrehmoment.','Revise el ajuste repetido y la retención en la unión real. La geometría de punta y el diámetro del tornillo no proporcionan una fuerza de retención ni un par de apriete universales.','Valutare regolazioni ripetute e tenuta sull’unione reale. Geometria della punta e diametro non forniscono da soli un valore universale di forza di ritegno o coppia di serraggio.','Vérifiez les réglages répétés et le maintien sur l’assemblage réel. La forme de l’extrémité et le diamètre de vis ne donnent pas à eux seuls une valeur universelle de force de maintien ou de couple de serrage.','反复调整与保持效果要在实际连接中评估。仅凭端型和螺丝直径，不能给出通用的保持力或拧紧扭矩。');
put('setNext','Vier Spitzenformen und Auswahl-Arbeitsblatt vergleichen','Comparar las cuatro puntas y la hoja de selección','Confrontare le quattro punte e la scheda di scelta','Comparer les quatre extrémités et la fiche de sélection','查看四种端型对比与选型表');

put('qualityTitle','Drei eindeutige Freigabepunkte festlegen','Establecer tres puntos claros de aprobación','Definire tre chiari passaggi di rilascio','Définir trois étapes claires de libération','把放行拆成三个明确的确认节点');
put('qualityIntro','Verknüpfen Sie Musterfreigabe, Losabnahme und Änderungsfreigabe über Zeichnungsstand und Merkmalskennungen. Vereinbaren Sie vor der Fertigung die für den Auftrag benötigten Unterlagen.','Use la revisión del plano y los identificadores de características para vincular muestras, aceptación del lote y cambios. Acuerde los registros del pedido antes de producir.','Usare revisione del disegno e identificativi delle caratteristiche per collegare approvazione dei campioni, accettazione del lotto e modifiche. Concordare i documenti dell’ordine prima della produzione.','Reliez approbation des échantillons, réception du lot et modifications par l’indice du plan et les identifiants des caractéristiques. Convenez des documents de la commande avant production.','用图纸版本和特征编号，把样品批准、批次验收与变更批准串起来。订单需要保留哪些记录，应在生产前约定。');
put('qualityOneTitle','Mustergrundlage freigeben','Aprobar la base de la muestra','Approvare la base del campione','Approuver la définition de l’échantillon','确认样品批准的依据');
put('qualityOne','Benennen Sie Zeichnungsstand, Musterroute, kritische Merkmale und Gegenstückreferenz. Dokumentieren Sie, ob die Vorlage Messwerte, Screening-Ergebnisse, Werkstoffunterlagen oder einen Montageversuch enthält.','Identifique revisión, ruta de la muestra, características críticas y referencia de las piezas acopladas. Indique si la entrega incluye mediciones, resultados de cribado, documentos de material o una prueba de montaje.','Identificare revisione, ciclo del campione, caratteristiche critiche e riferimento dei componenti accoppiati. Indicare se la presentazione comprende misure, esiti di selezione, documenti del materiale o una prova di montaggio.','Identifiez l’indice du plan, la gamme de l’échantillon, les caractéristiques critiques et les pièces en regard. Indiquez si le dossier comprend mesures, résultats de tri, documents matière ou essai d’assemblage.','明确图纸版本、样品采用的工艺路线、关键特征和配合件依据。注明提交的是实测值、筛选结果、材料文件，还是装配试验记录。');
put('qualityTwoTitle','Los im Lieferzustand abnehmen','Aceptar el lote en su estado de suministro','Accettare il lotto nello stato di fornitura','Réceptionner le lot dans son état de livraison','按最终交付状态验收批次');
put('qualityTwo','Vereinbaren Sie für jedes Merkmal Methode, Prüfzeitpunkt, Umfang und Aufzeichnung. Unterscheiden Sie Einzelmessungen von Gut-/Schlecht-Screening und legen Sie externe Prüfberichte separat fest.','Acuerde método, etapa, cobertura y registro para cada característica. Distinga las mediciones individuales del cribado conforme/no conforme y especifique aparte los informes de ensayos externos.','Per ogni caratteristica concordare metodo, fase, copertura e registrazione. Distinguere misure individuali dalla selezione conforme/non conforme e specificare separatamente eventuali rapporti di prove esterne.','Pour chaque caractéristique, convenez de la méthode, de l’étape, de la couverture et de l’enregistrement. Distinguez les mesures individuelles du tri conforme/non conforme et précisez séparément les rapports d’essais externes.','逐项约定检测方法、工序阶段、覆盖范围和记录形式。单件实测值与合格／不合格筛选结果分开记录，外部检测报告也应单独明确。');
put('qualityThreeTitle','Änderungen und Abweichungen klären','Resolver cambios y desviaciones','Gestire modifiche e scostamenti','Traiter modifications et écarts','处理变更与偏差');
put('qualityThree','Halten Sie betroffene Anforderung, vorgeschlagene Behandlung und Zustimmung vor der Freigabe fest. Bei Änderungen an Zeichnung, Route oder Oberfläche ist festzulegen, welche Prüfungen und Musterfreigaben zu wiederholen sind.','Registre el requisito afectado, la disposición propuesta y su aprobación antes de liberar. Si cambia el plano, la ruta o el acabado, identifique qué controles y aprobaciones de muestra deben repetirse.','Registrare requisito interessato, trattamento proposto e approvazione prima del rilascio. Se cambiano disegno, ciclo o finitura, individuare quali controlli e approvazioni dei campioni ripetere.','Consignez avant libération l’exigence concernée, la décision proposée et son approbation. Si le plan, la gamme ou la finition change, identifiez les contrôles et approbations d’échantillons à renouveler.','放行前记录受影响的要求、拟处理方式和批准意见。图纸、工艺路线或表面处理发生变化时，明确哪些检查和样品批准需要重新进行。');
put('qualityNext','Merkmalsbezogenen Prüfplan erstellen','Crear un plan de inspección por características','Preparare il piano di controllo per caratteristica','Construire un plan de contrôle par caractéristique','逐项建立特征检验计划');
put('inspectionTitle','Jedem Merkmal den passenden Prüfnachweis zuordnen','Asignar a cada característica su evidencia de inspección','Associare a ogni caratteristica la corretta evidenza di controllo','Associer chaque caractéristique à sa preuve de contrôle','每项特征，都要对应合适的验收依据');
put('inspectionIntro','Teilen Sie eine Schulterschraube mit Bohrung in einzelne Prüfmerkmale auf. Das Planungsbeispiel zeigt, warum Außenkonturaufnahme, Gewindelehre und Innenprüfung nicht austauschbar sind.','En un tornillo con hombro y taladro, separe las características. Este ejemplo de planificación muestra por qué la imagen exterior, un calibre de rosca y una comprobación interna no son intercambiables.','Per una vite a spallamento con foro, suddividere il controllo in caratteristiche distinte. L’esempio mostra perché immagine esterna, calibro del filetto e controllo interno non sono intercambiabili.','Pour une vis à épaulement percée, séparez les caractéristiques à contrôler. Cet exemple de planification montre pourquoi image extérieure, calibre de filetage et contrôle intérieur ne sont pas interchangeables.','以带孔台阶螺丝为例，把检查拆成不同特征。这个计划示例说明：外部相机结果、螺纹量规与内部孔道检查各有用途，不能相互替代。');
put('featureHeading','Zeichnungsmerkmal','Característica del plano','Caratteristica a disegno','Caractéristique du plan','图纸特征');
put('methodHeading','Zu vereinbarendes Verfahren','Método por acordar','Metodo da concordare','Méthode à convenir','需约定的方法');
put('stageHeading','Abnahmestufe','Etapa de aceptación','Fase di accettazione','Étape de réception','验收阶段');
put('recordHeading','Aufzubewahrender Nachweis','Registro que conservar','Registrazione da conservare','Enregistrement à conserver','保留的记录');
put('inspectionProfile','Sichtbare Schulterkontur','Perfil visible del hombro','Profilo visibile del gambo calibrato','Profil visible de l’épaulement','可见肩轴轮廓');
put('inspectionProfileMethod','Geeignetes kalibriertes optisches Messverfahren; Lage und Programm für das Merkmal validieren.','Medición óptica calibrada adecuada; valide la presentación y el programa para la característica.','Misura ottica calibrata idonea; validare posizionamento e programma per la caratteristica.','Mesure optique étalonnée adaptée ; validez la présentation et le programme pour la caractéristique.','采用合适且经过校准的光学测量；针对该特征验证摆放方式与检测程序。');
put('inspectionProfileStage','Endgültiger Lieferzustand; Zwischenprüfung ergänzen, wenn spätere Arbeit das Merkmal verdeckt.','Estado final de suministro; añada un control intermedio si las operaciones posteriores ocultan la característica.','Stato finale di fornitura; aggiungere un controllo intermedio se operazioni successive nascondono la caratteristica.','État final de livraison ; ajoutez un contrôle intermédiaire si une opération ultérieure masque la caractéristique.','按最终交付状态验收；若后续工序会遮蔽该特征，再增加中间检查。');
put('inspectionProfileRecord','Merkmalskennung, Programm-/Methodenstand, Grenzen, Umfang sowie Mess- oder Screening-Ergebnis.','Identificador, revisión del programa o método, límites, cobertura y resultado medido o de cribado.','Identificativo, revisione di programma/metodo, limiti, copertura ed esito di misura o selezione.','Identifiant, version du programme ou de la méthode, limites, couverture et résultat de mesure ou de tri.','特征编号、程序／方法版本、限值、覆盖范围，以及实测或筛选结果。');
put('inspectionThread','Gewinde und nutzbarer Eingriff','Rosca y acoplamiento útil','Filetto e impegno utile','Filetage et engagement utile','螺纹与有效旋合');
put('inspectionThreadMethod','Vorgeschriebene Gewindelehren; bei Bedarf nutzbare Länge zusätzlich prüfen.','Calibres de rosca especificados y, cuando proceda, una comprobación independiente de longitud útil.','Calibri filettati previsti e, se richiesto, controllo separato della lunghezza utile.','Calibres de filetage spécifiés et, si nécessaire, contrôle distinct de la longueur utile.','使用规定的螺纹量规；需要时另行检查有效牙长。');
put('inspectionThreadStage','Nach den Arbeitsgängen, die das gelieferte Gewinde beeinflussen.','Después de las operaciones que afectan a la rosca suministrada.','Dopo le operazioni che modificano il filetto fornito.','Après les opérations affectant le filetage livré.','在影响最终螺纹状态的工序完成后检查。');
put('inspectionThreadRecord','Gewindebezeichnung, Lehrenkennung, Ergebnis und Anforderung an die nutzbare Länge.','Designación de rosca, identificación del calibre, resultado y requisito de longitud útil.','Designazione del filetto, identificativo del calibro, esito e requisito di lunghezza utile.','Désignation du filetage, identification du calibre, résultat et exigence de longueur utile.','螺纹标注、量规标识、检查结果及有效牙长要求。');
put('inspectionBore','Innenkanal und Bohrungskreuzung','Conducto interno e intersección','Passaggio interno e incrocio','Passage intérieur et intersection','内部孔道及交汇处');
put('inspectionBoreMethod','Geeignete zugängliche Bohrungsmessung und eine separat vereinbarte Prüfung der Innenkanten.','Medición del taladro accesible adecuada y comprobación de la arista interna acordada por separado.','Misura idonea del foro accessibile e controllo dello spigolo interno concordato separatamente.','Mesure adaptée de l’alésage accessible et contrôle de l’arête intérieure convenu séparément.','对可进入的孔段选用合适测量方式，内部边缘的检查方法单独约定。');
put('inspectionBoreStage','Bevor Verschluss oder Montage den Zugang begrenzen; geforderten Endzustand bestätigen.','Antes de que el cierre o montaje limiten el acceso; confirme el estado final requerido.','Prima che chiusura o montaggio limitino l’accesso; confermare lo stato finale richiesto.','Avant que la fermeture ou le montage ne limite l’accès ; confirmez l’état final requis.','在封闭或装配限制内部检查之前完成，并确认要求的最终状态。');
put('inspectionBoreRecord','Bohrungs-/Kantenanforderung, Methode, Prüfzeitpunkt, Ergebnis und Zugangsbegrenzungen.','Requisito de taladro y arista, método, etapa, resultado y limitaciones de acceso.','Requisito di foro e spigolo, metodo, fase, esito e limiti di accesso.','Exigence de l’alésage et de l’arête, méthode, étape, résultat et limites d’accès.','孔与边缘要求、方法、阶段、结果，以及检查可达性的限制。');
put('inspectionFunction','Anlage, Bewegung oder Haltefunktion','Asiento, movimiento o retención','Appoggio, movimento o ritegno','Appui, mouvement ou retenue','贴合、运动或保持功能');
put('inspectionFunctionMethod','Versuch mit eindeutig benannten Gegenstücken und vereinbartem Montageablauf.','Prueba con las piezas acopladas identificadas y un procedimiento de montaje acordado.','Prova con componenti accoppiati identificati e procedura di montaggio concordata.','Essai avec les pièces en regard identifiées et une procédure d’assemblage convenue.','使用已明确版本的配合件，按约定的装配程序进行验证。');
put('inspectionFunctionStage','Musterfreigabe und auftragsspezifisch festgelegte Wiederholungsprüfungen.','Aprobación de muestras y comprobaciones repetidas previstas para el pedido.','Approvazione dei campioni ed eventuali controlli ripetuti previsti dall’ordine.','Approbation des échantillons et contrôles répétés prévus pour la commande.','样品批准时验证，并按订单约定安排必要的重复检查。');
put('inspectionFunctionRecord','Stand des Gegenstücks, Kriterium, Ergebnis, Abweichung und Zustimmung.','Revisión de la pieza acoplada, criterio, resultado, desviación y aprobación.','Revisione del componente accoppiato, criterio, esito, scostamento e approvazione.','Indice de la pièce en regard, critère, résultat, écart et approbation.','配合件版本、判定要求、结果、偏差和批准意见。');
put('inspectionClose','Bestätigen Sie bei der Angebotserstellung Geräteignung, externe Prüfungen und Berichtsumfang. Die Matrix ist ein Planungsbeispiel, kein ausgefüllter Prüfbericht.','Confirme en la oferta la idoneidad del equipo, las pruebas externas y los informes. La matriz es un ejemplo de planificación, no un informe de inspección completado.','Confermare in fase di preventivo idoneità degli strumenti, prove esterne e documentazione. La matrice è un esempio di pianificazione, non un rapporto di controllo compilato.','Confirmez au devis l’adéquation des équipements, les essais externes et le contenu des rapports. Cette matrice est un exemple de planification, pas un rapport de contrôle réalisé.','报价阶段确认设备是否适用、是否安排外部检测，以及报告包含什么。此表是检验计划示例，不是已经完成的检测报告。');
put('inspectionImage','Illustration einer CCD-Sichtprüfung zur Erläuterung der Methode; kein Foto von ZUFEK-Anlagen.','Ilustración de inspección CCD para explicar el método; no es una fotografía de equipos de ZUFEK.','Illustrazione di controllo CCD per spiegare il metodo; non è una fotografia di attrezzature ZUFEK.','Illustration du contrôle CCD pour expliquer la méthode ; il ne s’agit pas d’une photographie d’un équipement ZUFEK.','CCD 视觉检测示意，用于说明方法，并非 ZUFEK 设备实拍。');

put('thumbTitle','Griffraum über den gesamten Verstellweg prüfen','Comprobar el espacio de agarre en todo el recorrido','Verificare lo spazio di presa lungo tutta la regolazione','Vérifier l’espace de préhension sur toute la course','在整个调节行程内检查握持空间');
put('thumbIntro','Rändelkopf, Gewindeführung und Kontaktende erfüllen unterschiedliche Aufgaben. Den eingebauten Mechanismus an den Verstellgrenzen prüfen, einschließlich vorgeschriebener Handschuhe oder Werkzeughalter.','Cabeza moleteada, soporte roscado y extremo cumplen funciones distintas. Revise el mecanismo instalado en los límites de recorrido, incluidos guantes o portaherramientas especificados.','Testa zigrinata, supporto filettato ed estremità svolgono compiti diversi. Verificare il meccanismo montato ai limiti della corsa, considerando guanti o portautensili previsti.','Tête moletée, support fileté et extrémité remplissent des fonctions différentes. Examinez le mécanisme monté en fin de course, avec les gants ou porte-outils prescrits.','滚花头、螺纹支撑与接触端各自承担不同作用。应在实际装配的行程极限位置检查，并考虑操作要求中的手套或工具夹持器。');
put('thumbOne','Griffraum: benachbarte Wände und den zum Drehen nötigen Raum berücksichtigen. Ein größerer Kopf hilft nur, wenn er erreichbar bleibt.','Agarre: incluya paredes cercanas y espacio para girar la cabeza. Una cabeza mayor solo ayuda si el operario puede alcanzarla.','Presa: includere pareti vicine e spazio per ruotare la testa. Una testa più grande aiuta soltanto se l’operatore riesce a raggiungerla.','Préhension : incluez les parois voisines et l’espace nécessaire pour tourner la tête. Une tête plus grande n’aide que si elle reste accessible.','握持空间：包括邻近壁面和转动头部所需的空间。头部加大，只有在操作人员确实能够握到时才有帮助。');
put('thumbTwo','Hub und Eingriff: Führung, nutzbare Gewindelänge und beide Endstellungen zeigen. Das Halten der Einstellung unabhängig von der Rändelung vereinbaren.','Recorrido y acoplamiento: muestre soporte, rosca útil y ambas posiciones límite. Acuerde la retención del ajuste por separado del moleteado.','Corsa e impegno: indicare supporto, filetto utile ed entrambe le posizioni limite. Definire il mantenimento della regolazione separatamente dalla zigrinatura.','Course et engagement : montrez support, filetage utile et positions extrêmes. Définissez le maintien du réglage séparément du moletage.','行程与旋合：标出支撑件、有效螺纹和两端位置。滚花便于握持，但调节位置如何保持应另行明确。');
put('thumbThree','Kontaktende: Gegenauflage oder Kontaktfläche und zulässige Spuren benennen. Rückkehr zur Referenzposition am tatsächlichen Kontakt prüfen.','Extremo: identifique apoyo o superficie y marcas admisibles. Evalúe el retorno a una referencia con el contacto real.','Estremità: identificare pattino o superficie e segni ammessi. Valutare il ritorno alla posizione di riferimento con il contatto effettivo.','Extrémité : identifiez patin ou surface et marques admises. Évaluez le retour à une référence avec le contact réel.','接触端：明确配合垫块或接触面及允许压痕，并在实际接触组合下检查能否返回基准位置。');
put('thumbOutcome','Für die Musterfreigabe Führung und Kontaktteil benennen, den vereinbarten Verstellablauf erproben und Position sowie Kontaktzustand dokumentieren. Handbetätigung ist kein gemessenes Anziehverfahren; bei gefordertem kontrolliertem Drehmoment eine gesonderte Methode festlegen.','Para aprobar muestras, identifique soporte y contacto, pruebe la secuencia acordada y registre posición y estado del contacto. El accionamiento manual no mide el apriete; defina otro método si se exige un par controlado.','Per approvare i campioni, identificare supporto e contatto, provare la sequenza concordata e registrare posizione e stato del contatto. L’azionamento manuale non misura il serraggio: specificare un metodo distinto quando serve coppia controllata.','Pour approuver les échantillons, identifiez support et pièce de contact, essayez la séquence convenue et consignez position et contact. La manœuvre manuelle ne mesure pas le serrage ; prévoyez une méthode distincte si un couple contrôlé est requis.','样品批准时应注明支撑与接触件，按约定顺序试调，记录位置和接触状态。手拧不是测量扭矩的锁紧方法；有受控扭矩要求时，应另定操作方法。');
put('thumbNext','Griff- und Verstellanforderungen vorbereiten','Preparar requisitos de agarre y ajuste','Preparare requisiti di presa e regolazione','Préparer les exigences de préhension et de réglage','整理握持与调节要求');
put('thumbMeta','Rändelschrauben nach Griffraum, Verstellweg, Kontaktende und Sicherung spezifizieren. Den eingebauten Mechanismus vor der Musterfreigabe prüfen.','Especifique tornillos moleteados según agarre, recorrido, contacto y bloqueo. Revise el mecanismo instalado antes de aprobar muestras.','Specificare viti zigrinate in base a presa, corsa, estremità e bloccaggio. Verificare il meccanismo montato prima di approvare i campioni.','Spécifiez les vis moletées selon préhension, course, extrémité et blocage. Examinez le mécanisme monté avant approbation des échantillons.','按握持净空、调节行程、接触端和锁定方式定制滚花手拧螺丝，样品批准前检查实际装配中的操作。');
put('slotTitle','Einführen, Drehen und Auflage getrennt prüfen','Revisar inserción, giro y apoyo por separado','Verificare separatamente inserimento, rotazione e appoggio','Examiner séparément insertion, rotation et appui','分别评审装入、转位和承压状态');
put('slotIntro','Die Skizze zeigt einen Kopf, der unter der Nutöffnung drehen soll. Ein vom Nutende eingeschobener T-Bolzen hat einen anderen Einbauweg. Die tatsächliche Einführart festlegen, statt jeden T-Kopf in jeder Nut als drehbar anzusehen.','El esquema muestra una cabeza diseñada para girar bajo la abertura. Un perno introducido desde el extremo sigue otro recorrido. Defina la entrada real; no suponga que toda cabeza en T gira en cualquier ranura.','Lo schema mostra una testa progettata per ruotare sotto l’apertura. Un bullone inserito dall’estremità della cava segue un altro percorso. Specificare l’ingresso reale senza presumere che ogni testa a T ruoti in ogni cava.','Le schéma montre une tête conçue pour tourner sous l’ouverture. Un boulon introduit par l’extrémité suit un autre trajet. Définissez l’insertion réelle sans supposer que toute tête en T peut tourner dans toute rainure.','图中示意的是可以在槽口下方转位的头部。由槽端滑入的 T 型螺栓采用另一种装入路线。应明确实际装入方式，不能默认每种 T 头都能在任意槽内旋转。');
put('slotOne','Einführen: Kopf in Einführlage mit Öffnung und Innenraum vergleichen. Geschlossene Nutenden oder Hindernisse im Einbauweg berücksichtigen.','Inserción: compare la cabeza orientada para entrar con abertura y cavidad. Incluya extremos cerrados u obstáculos en el recorrido.','Inserimento: confrontare la testa orientata per entrare con apertura e cavità. Includere estremità chiuse o ostacoli lungo il percorso.','Insertion : comparez la tête orientée à l’ouverture et à la cavité. Incluez extrémités fermées et obstacles du trajet.','装入：按装入方向比较头部与槽口及内部空腔，考虑封闭槽端和沿途障碍。');
put('slotTwo','Drehen: vollständigen Schwenkraum unter den Nutstegen prüfen, einschließlich Ecken, Hals und Nachbarteilen. Ein Kopf kann in Endlage passen und beim Drehen dennoch klemmen.','Giro: compruebe toda la envolvente bajo los labios, incluidas esquinas, cuello y piezas próximas. Una cabeza puede caber al final y atascarse al girar.','Rotazione: verificare l’intero ingombro sotto le spalle, con spigoli, collo e pezzi vicini. Una testa può entrare nella posizione finale ma bloccarsi durante la rotazione.','Rotation : vérifiez toute l’enveloppe balayée sous les lèvres, avec coins, col et pièces voisines. Une tête peut convenir en position finale mais coincer pendant la rotation.','转位：检查槽肩下的完整旋转扫掠范围，包括头部棱角、颈部和邻近件。最终角度能放下，不代表旋转过程不会卡住。');
put('slotThree','Auflage: tragende Unterseiten beim Anziehen zeigen. Anlage, nutzbaren Eingriff und vorgesehene Verdrehsicherung in der tatsächlichen Nut bestätigen.','Apoyo: muestre qué caras inferiores soportan la cabeza al apretar. Confirme asiento, acoplamiento útil y contacto antigiro en la ranura real.','Appoggio: indicare le facce inferiori che sostengono la testa serrata. Confermare appoggio, impegno utile e antirotazione nella cava reale.','Appui : montrez les faces inférieures qui portent la tête serrée. Confirmez appui, engagement utile et antirotation dans la rainure réelle.','承压：标明锁紧后由哪些槽肩底面支撑头部，在实际槽内确认落座、有效旋合和预定防转接触。');
put('slotOutcome','Nutquerschnitt und Montagefolge von offen bis gespannt mit der Bolzenzeichnung senden. Musterprüfung nach Einführen, vorgesehener Drehung und endgültiger Anlage trennen. Die Profil-Nenngröße belegt weder austauschbare Kopfgeometrie noch eine zulässige Klemmkraft.','Envíe sección de ranura y secuencia de montaje junto al plano del perno. Distinga inserción, giro previsto y asiento final en las muestras. El tamaño nominal del perfil no demuestra intercambiabilidad de cabezas ni capacidad de apriete.','Inviare sezione della cava e sequenza da aperto a serrato insieme al disegno. Distinguere inserimento, rotazione prevista e appoggio finale nei controlli. La misura nominale del profilato non dimostra intercambiabilità della testa o capacità di serraggio.','Envoyez section de rainure et séquence de montage avec le plan du boulon. Distinguez insertion, rotation prévue et appui final dans les contrôles. La taille nominale du profilé ne prouve ni interchangeabilité de tête ni capacité de bridage.','请随螺栓图纸提供槽截面及从装入到夹紧的装配顺序。样品检查分别记录装入、设计要求的转位和最终落座。型材公称规格不能直接证明头部可互换，也不能当作夹紧载荷等级。');
put('slotNext','Nut vor Festlegung der Kopfmaße vermessen','Medir la ranura antes de fijar las cotas de cabeza','Misurare la cava prima di fissare le quote della testa','Mesurer la rainure avant de définir la tête','确定头部尺寸前先测量槽结构');
put('slotMeta','T-Nutenbolzen nach tatsächlicher Nut, Einführweg, Schwenkraum und Auflage auslegen. Einbaupassung vor Freigabe der Kopfgeometrie vergleichen.','Defina pernos en T según ranura, entrada, giro y apoyo reales. Revise el ajuste instalado antes de aprobar la cabeza.','Definire bulloni per cave a T secondo cava, ingresso, rotazione e appoggio reali. Verificare il montaggio prima di approvare la testa.','Définissez les boulons en T selon rainure, insertion, rotation et appui réels. Comparez le montage avant de libérer la géométrie de tête.','按实际槽结构、装入路径、旋转包络和承压面定制 T 型螺栓，确定头部几何前先核对装配配合。');

put('studTitle','Ende A, Mittelteil und Ende B eindeutig zuordnen','Identificar extremo A, zona central y extremo B','Identificare estremità A, parte centrale ed estremità B','Identifier extrémité A, partie centrale et extrémité B','让 A 端、中间段与 B 端清楚可辨');
put('studIntro','Die Skizze zeigt bewusst unterschiedliche Gewindeenden. Beide unabhängig spezifizieren, dann den Mittelteil für Einbau, Anlage oder Werkzeugzugang festlegen.','El esquema muestra extremos distintos de forma deliberada. Especifique cada uno y después la zona central que controla montaje, asiento o acceso.','Lo schema mostra volutamente estremità filettate diverse. Specificarle separatamente, poi definire la parte centrale per montaggio, appoggio o accesso utensile.','Le schéma montre volontairement des extrémités différentes. Spécifiez chacune, puis la partie centrale qui détermine montage, appui ou accès d’outil.','图中刻意将两端螺纹画成不同结构。两端要求分别规定，再明确影响安装、落座或工具空间的中间段。');
put('studOne','Ende A: Gewindesystem, Durchmesser, Steigung, Drehsinn, nutzbare Länge und Eingriff angeben. Zugehöriges Gegenstück benennen.','Extremo A: indique sistema, diámetro, paso, sentido, longitud útil y acoplamiento. Identifique la pieza que recibe este extremo.','Estremità A: indicare sistema, diametro, passo, senso, lunghezza utile e impegno. Identificare il pezzo che riceve questa estremità.','Extrémité A : indiquez système, diamètre, pas, sens, longueur utile et engagement. Identifiez la pièce qui reçoit cette extrémité.','A 端：注明牙制、直径、螺距、旋向、有效牙长和旋合要求，并指出这一端装入哪个配合件。');
put('studTwo','Mittelteil: Schultern und Schlüsselflächen von benannten Bezügen bemaßen. Einbaufolge und verbleibenden Werkzeugraum nach Montage des ersten Endes prüfen.','Zona central: acote hombros y planos de llave desde referencias identificadas. Revise montaje y espacio de herramienta tras instalar el primer extremo.','Parte centrale: quotare spallamenti e piani chiave dai riferimenti definiti. Verificare ordine di montaggio e spazio utensile dopo la prima estremità.','Partie centrale : cotez épaulements et plats de clé depuis les références nommées. Examinez ordre de montage et accès restant après pose de la première extrémité.','中间段：按指定基准标注台阶与扳手位，评审安装先后，以及第一端装好后剩余的工具空间。');
put('studThree','Ende B: eigene Gewinde- und Endoberflächenabnahme anwenden. Eine praktikable Endkennzeichnung festlegen, die kontrollierte Flächen nicht beschädigt.','Extremo B: aplique su propia aceptación de rosca y acabado. Defina una identificación práctica que no dañe superficies controladas.','Estremità B: applicare la propria accettazione di filetto e finitura. Definire un’identificazione pratica senza danneggiare le superfici controllate.','Extrémité B : appliquez sa propre réception de filetage et finition. Définissez un repérage pratique sans endommager les surfaces contrôlées.','B 端：采用这一端独立的螺纹与最终表面验收要求，约定不损伤受控表面的实际识别方式。');
put('studOutcome','Wenn die Orientierung zählt, A/B-Kennzeichnung auf Zeichnung, Lehrenprotokoll und Verpackung beibehalten. Beide Gegenstückstände mit dem freigegebenen Muster dokumentieren; auch bei Änderung nur eines Endes Zugang und Eingriff am anderen prüfen.','Cuando importe la orientación, conserve A/B en plano, registro de calibres y etiqueta. Registre ambas revisiones acopladas con la muestra; cambiar un extremo exige revisar acceso y acoplamiento en el otro.','Quando l’orientamento conta, mantenere A/B su disegno, controllo calibri ed etichetta. Registrare entrambi i pezzi accoppiati col campione: modificare un’estremità richiede riesaminare accesso e impegno dell’altra.','Lorsque l’orientation compte, conservez A/B sur plan, contrôle des calibres et étiquette. Consignez les deux indices des pièces en regard avec l’échantillon ; modifier une extrémité impose de revoir accès et engagement à l’autre.','方向有要求时，在图纸、量规检查记录及包装标签上保留 A/B 标识。批准样品关联两侧配合件版本；即使只改一端，也要重新考虑另一端的安装空间和旋合。');
put('studNext','Kennzeichnung und Prüfung unterschiedlicher Gewinde abstimmen','Coordinar identificación e inspección de roscas distintas','Coordinare identificazione e controllo dei filetti diversi','Coordonner repérage et contrôle des filetages différents','协调两端异牙的识别与检查');
put('studMeta','Jedes Ende eines Sonderstehbolzens nach Gewindesystem, Drehsinn, Eingriff und Kennzeichnung spezifizieren. Schlüsselzugang, Lehren und Verpackung abstimmen.','Especifique cada extremo del espárrago: sistema de rosca, sentido, acoplamiento e identificación. Coordine acceso de llave, calibres y embalaje.','Specificare ogni estremità del prigioniero: sistema, senso, impegno e identificazione. Coordinare accesso chiave, calibri e imballaggio.','Spécifiez chaque extrémité du goujon : système, sens, engagement et repérage. Coordonnez accès de clé, calibres et emballage.','为非标双头螺柱分别规定两端牙制、旋向、有效旋合及识别方法，同时协调扳手空间、量规检查和包装。');
put('eccentricTitle','Bezugsachse, Exzentermitte und Winkelreferenz festlegen','Definir eje de referencia, centro excéntrico y orientación angular','Definire asse di riferimento, centro eccentrico e riferimento angolare','Définir axe de référence, centre excentrique et repère angulaire','明确基准轴、偏心中心与角度基准');
put('eccentricIntro','Links sind Einbauachse A und Exzentermitte B getrennt dargestellt, rechts eine gesonderte Winkelreferenz. Dies sind Zeichnungsbeziehungen, keine aus der Außenform abgeleiteten Toleranzwerte.','La vista izquierda distingue eje de montaje A y centro excéntrico B. La derecha muestra una referencia angular separada. Son relaciones del plano, no tolerancias deducidas del contorno.','La vista sinistra distingue asse di montaggio A e centro eccentrico B. A destra è illustrato un riferimento angolare distinto. Sono relazioni di disegno, non tolleranze dedotte dal profilo.','La vue gauche distingue axe de montage A et centre excentrique B. À droite figure un repère angulaire distinct. Ce sont des relations de plan, pas des tolérances déduites du contour.','左图将安装轴线 A 与偏心中心 B 分开表示，右图单独说明角度基准。这些是图纸中需要定义的关系，不是从外形猜测出的公差值。');
put('eccentricOne','Bezugsachse A: Merkmal für die Einbauachse und dessen Aufnahme bei der Prüfung festlegen. Für eine Gewindefläche die Bezugsinterpretation vereinbaren.','Eje A: defina qué característica establece el eje instalado y cómo se posiciona al medir. Una superficie roscada requiere acordar la interpretación de referencia.','Asse A: definire la caratteristica che stabilisce l’asse montato e il posizionamento durante il controllo. Concordare l’interpretazione del riferimento su superfici filettate.','Axe A : définissez l’élément qui établit l’axe monté et sa mise en position au contrôle. Une surface filetée demande une interprétation convenue de la référence.','基准轴 A：明确哪个特征建立装机轴线，以及检测时怎样定位；以螺纹面建立基准时，应约定具体解释和定位方式。');
put('eccentricTwo','Mitte B und Versatz: Exzentermerkmal mit Größe und kontrollierter Form relativ zu A bemaßen. Gegenkontakt oder Folger zeigen.','Centro B y desplazamiento: acote la parte excéntrica respecto a A, con tamaño y forma controlada. Muestre contacto acoplado o seguidor.','Centro B ed eccentricità: quotare l’elemento eccentrico rispetto ad A, con dimensione e forma controllata. Indicare contatto o elemento seguace.','Centre B et décalage : cotez l’élément excentrique par rapport à A, avec taille et forme contrôlée. Montrez contact ou suiveur.','中心 B 与偏心量：相对 A 标注偏心特征，包含其尺寸和受控形状，并画出配合接触件或从动件。');
put('eccentricThree','Winkelreferenz: Nullrichtung, winkelgebundene Fläche oder Antrieb und zulässigen Verstellbereich benennen. Einstellung zum montierten Kontakt, nicht nur zum losen Teil, zuordnen.','Referencia angular: identifique cero, planos o accionamientos orientados y rango permitido. Relacione el ajuste con el contacto montado, no solo con la pieza suelta.','Riferimento angolare: identificare zero, piani o impronte orientati e campo ammesso. Collegare la regolazione al contatto montato, non soltanto al pezzo libero.','Repère angulaire : identifiez zéro, plat ou entraînement orienté et plage admise. Reliez le réglage au contact monté, pas seulement à la pièce libre.','角度基准：规定零位方向、有定向要求的平面或驱动槽，以及允许调节范围。设定值应对应装配后的接触状态，而不只是散件角度。');
put('eccentricOutcome','Messaufbau für festgelegten Versatz und Winkelbeziehung vereinbaren, dann Bewegung im Gegenaufbau erproben. Eine reine Außendurchmesserprüfung belegt weder Exzentrizität noch Orientierung oder den Verstellraum mit montierten Nachbarteilen.','Acuerde el montaje de medida para desplazamiento y ángulo y pruebe después el movimiento en el conjunto. Medir el diámetro exterior no demuestra excentricidad, orientación ni ajuste disponible con piezas próximas.','Concordare il piazzamento di misura per eccentricità e angolo, poi provare il movimento nell’assieme. Il solo diametro esterno non verifica eccentricità, orientamento o regolazione disponibile con i pezzi adiacenti montati.','Convenez du montage de mesure du décalage et de l’angle, puis essayez le mouvement dans l’assemblage. Le seul diamètre extérieur n’établit ni excentricité, ni orientation, ni réglage disponible avec les pièces voisines.','先约定偏心量和角度关系的测量装夹，再在配合装配中试验运动。只筛选外径，不能证明偏心量、方向或装上邻近件后真正可用的调节范围。');
put('eccentricNext','Exzenterbezüge und Prüfaufnahme spezifizieren','Especificar referencias excéntricas y posicionamiento de inspección','Specificare riferimenti eccentrici e posizionamento di controllo','Spécifier références excentriques et mise en position au contrôle','规定偏心基准及检测定位');
put('eccentricMeta','Exzenterschrauben nach Bezugsachse, versetzter Mitte und Winkelreferenz definieren. Verstellraum mit Fertigungsaufnahme und Endprüfung verknüpfen.','Defina tornillos excéntricos por eje, centro desplazado y referencia angular. Relacione ajuste, posicionamiento de mecanizado e inspección final.','Definire viti eccentriche con asse, centro disassato e riferimento angolare. Collegare regolazione, piazzamento produttivo e controllo finale.','Définissez les vis excentriques par axe, centre décalé et repère angulaire. Reliez réglage, mise en position d’usinage et contrôle final.','通过基准轴、偏心中心与角度基准定义偏心螺丝，将调节包络与加工装夹和最终检查联系起来。');

export function applyPracticalReview(){
 for(const key of Object.keys(practicalCopy))if(!review[practicalCopy[key]])throw Error('Missing practical localization '+key);
 fs.writeFileSync('translations/practical-review.json',JSON.stringify(review,null,2)+'\n');
 for(const locale of ['de','es','it','fr','zh']){const file='translations/'+locale+'.json',dictionary=JSON.parse(fs.readFileSync(file,'utf8'));for(const [source,values]of Object.entries(review))dictionary[source]=values[locale];fs.writeFileSync(file,JSON.stringify(dictionary,null,2)+'\n');}
 return Object.keys(review).length;
}
if(process.argv[1]?.replaceAll('\\','/').endsWith('/practical-localization.mjs'))console.log('Applied practical content translations: '+applyPracticalReview());
